output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts must not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "Before entering a single-file aisle, the agent must already have left the cart behind.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": "hasCart",
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "If the agent parks a cart at an aisle mouth, they must later retrieve it.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "hasCart",
              "aisleMouth",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "aisleMouth",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cart_required_except_narrow_aisle_visit",
    "text": "Past the entrance area, the agent may be without a cart only inside a single-file aisle or at its cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "entranceArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "entranceArea",
            "singleFileAisle",
            "aisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_station_first",
    "text": "At the start of a shopping trip, the agent is obliged to use the cart station before doing the rest of the trip.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)"
      },
      "events": {
        "takeCartFromStation": {
          "pre": {
            "and": [
              "cartStation",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartFromStation"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The agent must not leave the supermarket without the shopping cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_eastbound_store_flow",
    "text": "The supermarket follows a one-way circulation rule in which westbound travel is prohibited.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  },
  {
    "id": "no_interaction_in_single_file_with_cart",
    "text": "Interactions inside single-file shelf aisles must be done on foot, not while holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  }
]
